// Photo variants generated by scripts/gen-photos.mjs. Each set lives in its own
// folder under src/assets/ ("hero", "footer") and holds a "landscape" series
// for desktop and a "portrait" series for phones, named <shape>-<width>.<ext>.
const FILES = import.meta.glob("./assets/{hero,footer}/*.{avif,webp}", {
  eager: true,
  query: "?url",
  import: "default",
}) as Record<string, string>;

export type PhotoSet = "hero" | "footer";
type Shape = "landscape" | "portrait";
type Ext = "avif" | "webp";

function files(set: PhotoSet, shape: Shape, ext: Ext) {
  return Object.entries(FILES)
    .map(([path, url]) => ({ path, url, w: Number(/-(\d+)\.\w+$/.exec(path)?.[1]) }))
    .filter(({ path }) => path.includes(`/${set}/${shape}-`) && path.endsWith(`.${ext}`))
    .sort((a, b) => a.w - b.w);
}

export function photoSrcset(set: PhotoSet, shape: Shape, ext: Ext) {
  return files(set, shape, ext)
    .map(({ url, w }) => `${url} ${w}w`)
    .join(", ");
}

// Plain `src` for browsers that ignore srcset: the largest desktop WebP.
export function photoFallback(set: PhotoSet) {
  return files(set, "landscape", "webp").at(-1)?.url;
}

export const PHONE = "(max-width: 720px)";
